        ApplyPowerDelegate apply = ApplyPowerDelegates.GetOrAdd(powerType, static type =>
            GenericApplyMethod.MakeGenericMethod(type).CreateDelegate<ApplyPowerDelegate>());
        apply(this, target, amount, applier);
    }

