    ModifyHpLostBeforeOstyLate = 1UL << 44,
    ModifyOrbPassiveTriggerCounts = 1UL << 45,
    ModifyShuffleOrder = 1UL << 46,
    ShouldDie = 1UL << 47,
    ShouldDieLate = 1UL << 48,
    ShouldDraw = 1UL << 49,
    ShouldPlay = 1UL << 50,
