        if (layout is null || !layout.Matches(source))
        {
            int slot = -1;
            if (source.Count <= MaxSharedLayoutLength)
            {
                uint hash = unchecked((uint)source.Count);
                for (int index = 0; index < source.Count; index++)
                    hash = unchecked(hash * 16777619u
