using System.Diagnostics;
using System.Text.Json;
namespace CombatSolver.Engine.Common;
internal static class PileProjectionProbe
{
    private sealed class Cell { public readonly long[] Calls = new long[7]; public readonly long[] Cards = new long[7]; public readonly long[] Selected = new long[7]; public readonly long[] Ticks = new long[7]; }
    private static readonly ThreadLocal<Cell> Cells = new(() => new Cell(), true);
    static PileProjectionProbe() => AppDomain.CurrentDomain.ProcessExit += (_, _) => Write();
    internal static void Record(int kind, int cards, int selected, long start)
    {
        long elapsed = Stopwatch.GetTimestamp() - start;
        Cell c = Cells.Value!; c.Calls[kind]++; c.Cards[kind] += cards; c.Selected[kind] += selected; c.Ticks[kind] += elapsed;
    }
    private static void Write()
    {
        string? path = Environment.GetEnvironmentVariable("PILE_PROJECTION_PROBE_OUTPUT");
        if (path is null) return;
        var names = new[] { "opaque-pile", "filter-refusal", "reused-indices", "wrapper-alias", "cold-indices", "root-filter-capture", "reserved" };
        var rows = Enumerable.Range(0,names.Length).Select(k => new { kind=names[k], calls=Cells.Values.Sum(c => c.Calls[k]), cards=Cells.Values.Sum(c => c.Cards[k]), selected=Cells.Values.Sum(c => c.Selected[k]), cumulativeMilliseconds=Cells.Values.Sum(c => c.Ticks[k])*1000d/Stopwatch.Frequency }).ToArray();
        File.WriteAllText(path,JsonSerializer.Serialize(new { diagnosticOnly=true, timedScope="pile projection query and root filter capture; accumulated thread wall duration before counter update", threadCells=Cells.Values.Count, rows },new JsonSerializerOptions { WriteIndented=true }));
    }
}

